import React, { useState, useEffect } from "react";
import mondaySdk from "monday-sdk-js";
import * as XLSX from "xlsx";

const monday = mondaySdk();

const App = () => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const [progress, setProgress] = useState(0);
  const [totalTasks, setTotalTasks] = useState(0);

  useEffect(() => {
    // Prevent the user from closing the tab while processing
    const warnUser = (event) => {
      if (uploading) {
        event.preventDefault();
        event.returnValue = "Processing is ongoing. Closing may interrupt it.";
      }
    };
    window.addEventListener("beforeunload", warnUser);
    return () => window.removeEventListener("beforeunload", warnUser);
  }, [uploading]);

  const handleFileChange = (event) => {
    setFile(event.target.files[0]);
  };

  const fetchItemsFromMonday = async (boardId) => {
    console.log("Fetching items for board:", boardId);
    const query = `query {
      boards(ids: [${boardId}]) {
        items_page(limit: 100) {
          items {
            id
            name
          }
        }
      }
    }`;

    try {
      const res = await monday.api(query);
      console.log("Fetched Items Response:", res);
      if (res.errors) {
        console.error("GraphQL Errors:", res.errors);
        return {};
      }
      const items = res?.data?.boards[0]?.items_page?.items || [];
      return Object.fromEntries(items.map((item) => [item.name.trim(), item.id]));
    } catch (error) {
      console.error("Error fetching items:", error);
      return {};
    }
  };

  const addCommentToTask = async (itemId, comment) => {
    const mutation = `mutation {
      create_update(item_id: ${itemId}, body: "${comment.replace(/"/g, '\\"')}") {
        id
      }
    }`;

    try {
      await monday.api(mutation);
      return true;
    } catch (error) {
      console.error(`Error adding comment to ${itemId}:`, error);
      return false;
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setMessage("Please select a file.");
      return;
    }

    setUploading(true);
    setMessage("Processing file... Please do not close this window.");
    setProgress(0);

    const reader = new FileReader();
    reader.onload = async (e) => {
      const workbook = XLSX.read(e.target.result, { type: "binary" });
      const sheetName = workbook.SheetNames[0];
      const sheet = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);

      if (!sheet.length || !sheet[0].Task || !sheet[0].Comment) {
        setMessage("Invalid file format. Ensure columns are 'Task' and 'Comment'.");
        setUploading(false);
        return;
      }

      try {
        const boardContext = await monday.get("context");
        const boardId = boardContext.data.boardId;
        const itemsMap = await fetchItemsFromMonday(boardId);

        let successCount = 0;
        setTotalTasks(sheet.length);

        for (let i = 0; i < sheet.length; i++) {
          const row = sheet[i];
          const taskName = row.Task.trim();
          const comment = row.Comment.trim();
          const itemId = itemsMap[taskName];

          if (itemId && (await addCommentToTask(itemId, comment))) {
            successCount++;
          }

          // Update progress percentage
          setProgress(((i + 1) / sheet.length) * 100);
        }

        setMessage(`✅ Successfully added comments to ${successCount} tasks.`);
      } catch (error) {
        setMessage("❌ Error processing file.");
        console.error(error);
      }

      setUploading(false);
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Arial", textAlign: "center" }}>
      <h2>Upload Excel File</h2>
      <input type="file" accept=".xlsx" onChange={handleFileChange} />
      <button onClick={handleUpload} disabled={uploading}>
        {uploading ? "Processing..." : "Upload & Process"}
      </button>
      <p>{message}</p>

      {uploading && (
        <div style={{ width: "100%", backgroundColor: "#ddd", marginTop: "10px" }}>
          <div
            style={{
              width: `${progress}%`,
              height: "20px",
              backgroundColor: "#4CAF50",
              textAlign: "center",
              lineHeight: "20px",
              color: "white",
            }}
          >
            {Math.round(progress)}%
          </div>
        </div>
      )}
    </div>
  );
};

export default App;